def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def prime_fib(n: int):
    def fibonacci(num):
        a, b = 0, 1
        for _ in range(num):
            a, b = b, a + b
        return a

    count = 0
    num = 1
    while count < n:
        num += 1
        fib_num = fibonacci(num)
        if is_prime(fib_num):
            count += 1

    return fib_num
